# The blocks are still outside the pan and only 30 actions remain. I will open both hands, withdraw vertically, and return to the initial joint poses for the final check.
s = get_observation()['state']
a = {k:list(s[k]) for k in ['left_ee_pose','right_ee_pose','left_ee_joint_state','right_ee_joint_state']}
for side in ['left','right']:
    a[side+'_ee_pose'][2] += 0.12
    a[side+'_ee_joint_state'] = [1]
for i in range(10):
    obs,reward,terminated,truncated,info = step(a)
    if terminated or truncated:
        break
if not (terminated or truncated):
    for i in range(20):
        obs,reward,terminated,truncated,info = step(origin_joints)
        if terminated or truncated:
            break
print('final',reward,terminated,truncated,info)

